"use client";

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { 
  ArrowLeftRight, 
  CheckCircle, 
  XCircle, 
  RefreshCw, 
  AlertTriangle,
  Info,
  Scan,
  Clock,
  Percent
} from "lucide-react";

const API_BASE = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000";

interface Reconciliation {
  id: number;
  debit_txn_id: number;
  credit_txn_id: number;
  debit_account_id: string;
  credit_account_id: string;
  amount: number;
  date_diff_days: number;
  match_confidence: number;
  match_type: string;
  status: string;
  deterministic_key: string;
  created_at: string;
  confirmed_at: string | null;
  debit_date: string;
  debit_date_iso: string;
  debit_description: string;
  debit_amount_paise: number;
  credit_date: string;
  credit_date_iso: string;
  credit_description: string;
  credit_amount_paise: number;
  amount_display: string;
  confidence_display: string;
}

interface PotentialMatch {
  debit_txn_id: number;
  credit_txn_id: number;
  debit_account_id: string;
  credit_account_id: string;
  amount: number;
  date_diff_days: number;
  match_confidence: number;
  match_type: string;
  deterministic_key: string;
  explanation: string;
  amount_display: string;
  confidence_display: string;
}

export default function ReconciliationPage() {
  const [reconciliations, setReconciliations] = useState<Reconciliation[]>([]);
  const [potentialMatches, setPotentialMatches] = useState<PotentialMatch[]>([]);
  const [loading, setLoading] = useState(true);
  const [scanning, setScanning] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState("pending");

  const fetchReconciliations = async (status?: string) => {
    try {
      setLoading(true);
      const url = status 
        ? `${API_BASE}/api/reconciliations?status=${status}`
        : `${API_BASE}/api/reconciliations`;
      const response = await fetch(url);
      if (!response.ok) throw new Error("Failed to fetch reconciliations");
      const data = await response.json();
      setReconciliations(data.reconciliations || []);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    } finally {
      setLoading(false);
    }
  };

  const scanForMatches = async () => {
    try {
      setScanning(true);
      setError(null);
      const response = await fetch(`${API_BASE}/api/reconciliations/scan`);
      if (!response.ok) throw new Error("Failed to scan for matches");
      const data = await response.json();
      setPotentialMatches(data.matches || []);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    } finally {
      setScanning(false);
    }
  };

  const batchInsertMatches = async () => {
    try {
      setError(null);
      const response = await fetch(`${API_BASE}/api/reconciliations/batch-insert`, {
        method: "POST",
      });
      if (!response.ok) throw new Error("Failed to insert matches");
      const data = await response.json();
      // Clear potential matches and refresh
      setPotentialMatches([]);
      fetchReconciliations("pending");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    }
  };

  const confirmReconciliation = async (id: number) => {
    try {
      setError(null);
      const response = await fetch(`${API_BASE}/api/reconciliations/${id}/confirm`, {
        method: "POST",
      });
      if (!response.ok) throw new Error("Failed to confirm reconciliation");
      fetchReconciliations(activeTab === "all" ? undefined : activeTab);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    }
  };

  const rejectReconciliation = async (id: number) => {
    try {
      setError(null);
      const response = await fetch(`${API_BASE}/api/reconciliations/${id}/reject`, {
        method: "POST",
      });
      if (!response.ok) throw new Error("Failed to reject reconciliation");
      fetchReconciliations(activeTab === "all" ? undefined : activeTab);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    }
  };

  useEffect(() => {
    fetchReconciliations("pending");
  }, []);

  const handleTabChange = (value: string) => {
    setActiveTab(value);
    if (value === "all") {
      fetchReconciliations();
    } else {
      fetchReconciliations(value);
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "pending":
        return <Badge variant="secondary"><Clock className="w-3 h-3 mr-1" />Pending</Badge>;
      case "confirmed":
        return <Badge variant="default" className="bg-green-600"><CheckCircle className="w-3 h-3 mr-1" />Confirmed</Badge>;
      case "rejected":
        return <Badge variant="destructive"><XCircle className="w-3 h-3 mr-1" />Rejected</Badge>;
      default:
        return <Badge variant="outline">{status}</Badge>;
    }
  };

  const getMatchTypeBadge = (matchType: string) => {
    switch (matchType) {
      case "exact":
        return <Badge variant="default" className="bg-green-600">Exact Match</Badge>;
      case "window":
        return <Badge variant="secondary">Date Window</Badge>;
      case "fuzzy":
        return <Badge variant="outline">Fuzzy</Badge>;
      case "manual":
        return <Badge variant="outline">Manual</Badge>;
      default:
        return <Badge variant="outline">{matchType}</Badge>;
    }
  };

  const getConfidenceColor = (confidence: number) => {
    if (confidence >= 0.8) return "text-green-600";
    if (confidence >= 0.6) return "text-amber-600";
    return "text-red-600";
  };

  return (
    <div className="container mx-auto py-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Cross-Account Reconciliation</h1>
          <p className="text-muted-foreground">
            Detect and confirm transfers between accounts
          </p>
        </div>
        <div className="flex gap-2">
          <Button onClick={scanForMatches} disabled={scanning} variant="outline">
            {scanning ? (
              <RefreshCw className="w-4 h-4 mr-2 animate-spin" />
            ) : (
              <Scan className="w-4 h-4 mr-2" />
            )}
            Scan for Matches
          </Button>
          {potentialMatches.length > 0 && (
            <Button onClick={batchInsertMatches}>
              Add All ({potentialMatches.length})
            </Button>
          )}
        </div>
      </div>

      {error && (
        <Alert variant="destructive">
          <AlertTriangle className="h-4 w-4" />
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      )}

      <Alert>
        <Info className="h-4 w-4" />
        <AlertDescription>
          <strong>Integrity-Safe Design:</strong> Reconciliation is metadata-only. 
          Confirming or rejecting matches does NOT modify any transaction records.
          The ledger remains immutable.
        </AlertDescription>
      </Alert>

      <Tabs value={activeTab} onValueChange={handleTabChange}>
        <TabsList>
          <TabsTrigger value="pending">Pending</TabsTrigger>
          <TabsTrigger value="confirmed">Confirmed</TabsTrigger>
          <TabsTrigger value="rejected">Rejected</TabsTrigger>
          <TabsTrigger value="all">All</TabsTrigger>
        </TabsList>

        <TabsContent value={activeTab} className="space-y-4">
          {loading ? (
            <Card>
              <CardContent className="py-8 text-center text-muted-foreground">
                <RefreshCw className="w-6 h-6 mx-auto animate-spin mb-2" />
                Loading reconciliations...
              </CardContent>
            </Card>
          ) : reconciliations.length === 0 ? (
            <Card>
              <CardContent className="py-8 text-center text-muted-foreground">
                <ArrowLeftRight className="w-8 h-8 mx-auto mb-2 opacity-50" />
                No reconciliations found
              </CardContent>
            </Card>
          ) : (
            reconciliations.map((rec) => (
              <Card key={rec.id}>
                <CardHeader className="pb-2">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <CardTitle className="text-lg">{rec.amount_display}</CardTitle>
                      {getMatchTypeBadge(rec.match_type)}
                      <span className={`flex items-center gap-1 text-sm font-medium ${getConfidenceColor(rec.match_confidence)}`}>
                        <Percent className="w-3 h-3" />
                        {rec.confidence_display}
                      </span>
                      {getStatusBadge(rec.status)}
                    </div>
                    {rec.status === "pending" && (
                      <div className="flex gap-2">
                        <Button
                          size="sm"
                          variant="default"
                          className="bg-green-600 hover:bg-green-700"
                          onClick={() => confirmReconciliation(rec.id)}
                        >
                          <CheckCircle className="w-4 h-4 mr-1" />
                          Confirm
                        </Button>
                        <Button
                          size="sm"
                          variant="destructive"
                          onClick={() => rejectReconciliation(rec.id)}
                        >
                          <XCircle className="w-4 h-4 mr-1" />
                          Reject
                        </Button>
                      </div>
                    )}
                  </div>
                  <CardDescription>
                    {rec.date_diff_days === 0 ? "Same day" : `${rec.date_diff_days} days apart`}
                    {" • "}Key: {rec.deterministic_key}
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="grid md:grid-cols-2 gap-4">
                    {/* Debit Transaction */}
                    <div className="border rounded-lg p-3">
                      <div className="flex items-center justify-between mb-2">
                        <span className="font-medium text-sm">{rec.debit_account_id}</span>
                        <Badge variant="outline" className="text-red-600 border-red-200">
                          Debit
                        </Badge>
                      </div>
                      <div className="text-sm text-muted-foreground">
                        {rec.debit_date_iso}
                      </div>
                      <div className="text-sm truncate" title={rec.debit_description}>
                        {rec.debit_description || "—"}
                      </div>
                      <div className="font-medium text-red-600 mt-1">
                        -{(rec.debit_amount_paise / 100).toLocaleString("en-IN", { style: "currency", currency: "INR" })}
                      </div>
                    </div>

                    {/* Credit Transaction */}
                    <div className="border rounded-lg p-3">
                      <div className="flex items-center justify-between mb-2">
                        <span className="font-medium text-sm">{rec.credit_account_id}</span>
                        <Badge variant="outline" className="text-green-600 border-green-200">
                          Credit
                        </Badge>
                      </div>
                      <div className="text-sm text-muted-foreground">
                        {rec.credit_date_iso}
                      </div>
                      <div className="text-sm truncate" title={rec.credit_description}>
                        {rec.credit_description || "—"}
                      </div>
                      <div className="font-medium text-green-600 mt-1">
                        +{(rec.credit_amount_paise / 100).toLocaleString("en-IN", { style: "currency", currency: "INR" })}
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))
          )}
        </TabsContent>
      </Tabs>

      {/* Potential Matches Section */}
      {potentialMatches.length > 0 && (
        <Card className="border-blue-200 bg-blue-50/50">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Scan className="w-5 h-5" />
              Potential Matches Found ({potentialMatches.length})
            </CardTitle>
            <CardDescription>
              Review and add these detected transfers to reconciliations
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-3">
            {potentialMatches.map((match, idx) => (
              <div key={idx} className="border rounded-lg p-3 bg-white">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      {getMatchTypeBadge(match.match_type)}
                      <span className={`flex items-center gap-1 text-sm font-medium ${getConfidenceColor(match.match_confidence)}`}>
                        <Percent className="w-3 h-3" />
                        {match.confidence_display}
                      </span>
                    </div>
                    <p className="text-sm">{match.explanation}</p>
                    <div className="flex gap-4 mt-2 text-xs text-muted-foreground">
                      <span>From: {match.debit_account_id}</span>
                      <span>To: {match.credit_account_id}</span>
                      <span>Amount: {match.amount_display}</span>
                    </div>
                  </div>
                  <div className="text-right">
                    <div className="text-sm font-medium">{match.amount_display}</div>
                    <div className="text-xs text-muted-foreground">Key: {match.deterministic_key}</div>
                  </div>
                </div>
              </div>
            ))}
          </CardContent>
        </Card>
      )}
    </div>
  );
}